import org.jsoup.Connection;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.FormElement;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.junit.Test;
import org.mockito.Mockito;
import java.nio.charset.Charset;
import static org.junit.Assert.*;

public class DocumentTest {
    @Test
    public void documentCOnstructorTest(){
        Document doc = new Document("http://test.com");
        assertNotNull(doc);
    }

    @Test
    public void createShellTest(){
        Document doc = Document.createShell("http://shell.com");
        assertNotNull(doc);
    }

    @Test
    public void locationTest() {
        Document doc = new Document("http://test.com");
        assertEquals("http://test.com", doc.location());
    }

    @Test
    public void connectionTest() {
        Connection mockConnection = Mockito.mock(Connection.class);
        Document doc = new Document("http://test.com");
		doc.connection(mockConnection);
        assertEquals(mockConnection, doc.connection());
    }

    @Test
    public void headTest() {
        Document doc = new Document("http://test.com");
        Element head = doc.head();
        assertNotNull(head);
    }

	@Test
    public void bodyTest() {
        Document doc = new Document("http://test.com");
        Element body = doc.body();
        assertNotNull(body);
    }

    @Test
    public void formsTest() {
        Document doc = new Document("http://test.com");
        assertNotNull(doc.forms());
    }

	@Test
    public void titleTest() {
        Document doc = new Document("http://test.com");
        doc.title("Test Title");
        assertEquals("Test Title", doc.title());
    }

    @Test
    public void createElementTest() {
        Document doc = new Document("http://test.com");
        assertNotNull(doc.createElement("div"));
    }

	@Test
    public void nodeNameTest() {
        Document doc = new Document("http://test.com");
        assertNotNull(doc.nodeName());
    }

	@Test
    public void charsetTest() {
        Document doc = new Document("http://test.com");
        Charset charset = Charset.forName("UTF-8");
        doc.charset(charset);
        assertEquals(charset, doc.charset());
    }

    @Test
    public void updateMetaCharsetElementTest(){
        Document doc = new Document("http://test.com");
        doc.updateMetaCharsetElement(true);
        assertEquals(true, doc.updateMetaCharsetElement());
    }

	@Test
    public void cloneTest() {
        Document original = new Document("http://test.com");
        Document clone = original.clone();
        assertNotNull(clone);
        assertNotSame(original, clone);
    }

	@Test
    public void parserTest() {
        Parser mockParser = Mockito.mock(Parser.class);
        Document doc = new Document("http://test.com");
        doc.parser(mockParser);
        assertEquals(mockParser, doc.parser());
    }
}
